-- Mystic connection options

INSERT INTO "class_ability_options" ("class_id", "pool_name", "name", "description", "prerequisites") VALUES

('b1000000-0000-0000-0000-000000000003', 'connection', 'Akashic',
 'You have tapped into the akashic record, a metaphysical library of all knowledge and experience. Your associated skills are Culture and Mysticism. Your 1st-level power is Akashic Knowledge (you can attempt any Recall Knowledge check using Mysticism). Your connection spells are: 1st-comprehend languages, 2nd-augury, 3rd-clairaudience/clairvoyance, 4th-divination, 5th-contact other plane, 6th-vision.',
 null),

('b1000000-0000-0000-0000-000000000003', 'connection', 'Empath',
 'You have an extraordinary ability to connect with the emotions of others. Your associated skills are Diplomacy and Sense Motive. Your 1st-level power is Empathy (you gain +4 to Sense Motive; you can detect surface emotions of creatures within 30 feet). Your connection spells are: 1st-charm person, 2nd-calm emotions, 3rd-suggestion, 4th-mind probe, 5th-telepathy, 6th-mass suggestion.',
 null),

('b1000000-0000-0000-0000-000000000003', 'connection', 'Healer',
 'You are a beacon of healing energy. Your associated skills are Medicine and Mysticism. Your 1st-level power is Healing Channel (as a standard action, you heal all living creatures within 30 feet by 1d6 + your mystic level). Your connection spells are: 1st-mystic cure, 2nd-remove condition, 3rd-mystic cure III, 4th-remove radioactivity, 5th-raise dead, 6th-regenerate.',
 null),

('b1000000-0000-0000-0000-000000000003', 'connection', 'Mindbreaker',
 'You have mastered the ability to assault and shatter minds. Your associated skills are Intimidate and Mysticism. Your 1st-level power is Share Pain (when you take damage, you can use a reaction to deal half that damage to a creature you have a mindlink with). Your connection spells are: 1st-mind thrust I, 2nd-inflict pain, 3rd-mind thrust III, 4th-confusion, 5th-feeblemind, 6th-mind thrust VI.',
 null),

('b1000000-0000-0000-0000-000000000003', 'connection', 'Overlord',
 'You have learned to bend the will of others to your own. Your associated skills are Intimidate and Mysticism. Your 1st-level power is Inexorable Influence (when a creature you have successfully used a compulsion effect on attempts to break free, it must roll twice and take the worse result). Your connection spells are: 1st-charm person, 2nd-hold person, 3rd-dominate person, 4th-hold monster, 5th-dominate monster, 6th-mass hold monster.',
 null),

('b1000000-0000-0000-0000-000000000003', 'connection', 'Star Shaman',
 'You have a deep bond with the void of space and the stars within it. Your associated skills are Mysticism and Piloting. Your 1st-level power is Walk the Void (you can survive in the vacuum of space; you gain a fly speed equal to your land speed in zero gravity). Your connection spells are: 1st-shooting stars, 2nd-darkvision, 3rd-irradiate, 4th-remove radioactivity, 5th-telekinesis, 6th-gravitational singularity.',
 null),

('b1000000-0000-0000-0000-000000000003', 'connection', 'Xenodruid',
 'You have developed a spiritual bond with the living creatures of the universe. Your associated skills are Life Science and Survival. Your 1st-level power is Speak with Animals (you can speak with animals as per the spell; this is not a spell-like ability). Your connection spells are: 1st-life bubble, 2nd-fog cloud, 3rd-tongues, 4th-reincarnate, 5th-commune with nature, 6th-baleful polymorph.',
 null);
